310	        <p class="code">    d = dis / wp.max(dis_len, 1e-6)</p>
311	        <p class="code">    spring_force = (</p>
312	        <p class="code">        wp.clamp(wp.exp(spring_Y[tid]),</p>
313	        <p class="code">                 low=spring_Y_min, high=spring_Y_max)</p>
314	        <p class="code">        * (dis_len / rest - 1.0) * d)</p>
315	        <p class="code">    v_rel = wp.dot(v2 - v1, d)</p>
316	        <p class="code">    dashpot_forces = dashpot_damping * v_rel * d</p>
317	        <p class="code">    overall_force = spring_force + dashpot_forces</p>
318	        <p class="code">    wp.atomic_add(f, idx1, overall_force)</p>
319	        <p class="code">    wp.atomic_sub(f, idx2, overall_force)</p>
